import{_ as t,o as s,c as i,ah as o}from"./chunks/framework.D4KxWb5R.js";const m=JSON.parse('{"title":"Communications et ressources","description":"","frontmatter":{},"headers":[],"relativePath":"guide/administration/communications.md","filePath":"src/guide/administration/communications.md"}'),r={name:"guide/administration/communications.md"};function n(a,e,u,l,c,d){return s(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="communications-et-ressources" tabindex="-1">Communications et ressources <a class="header-anchor" href="#communications-et-ressources" aria-label="Permalink to &quot;Communications et ressources&quot;">​</a></h1><p>Ouvert au PDG et au Pôle Support Partenaires &amp; Clients.</p><h2 id="communications" tabindex="-1">Communications <a class="header-anchor" href="#communications" aria-label="Permalink to &quot;Communications&quot;">​</a></h2><p>Une communication est une annonce publiée dans l&#39;intranet, visible dès son enregistrement.</p><ol><li><p><strong>Administration → Communications → Nouvelle communication</strong>.</p></li><li><p>Saisissez le <strong>titre</strong> et le <strong>message</strong>, et choisissez la <strong>langue de rédaction</strong> (anglais ou français).</p></li><li><p>Choisissez les <strong>destinataires</strong> :</p><table tabindex="0"><thead><tr><th>Destinataires</th><th>Qui la reçoit</th></tr></thead><tbody><tr><td>Tout M&#39;City</td><td>Tous les comptes</td></tr><tr><td>Produit</td><td>Les comptes dont le périmètre couvre le produit</td></tr><tr><td>Zone</td><td>Les comptes à qui la zone est attribuée, ou dont un bureau est dans la zone</td></tr><tr><td>Bureau</td><td>Les comptes à qui le bureau est attribué (RH et Finance couvrent tous les bureaux)</td></tr><tr><td>Département</td><td>Les comptes rattachés au département</td></tr><tr><td>Poste</td><td>Les comptes qui ont ce poste</td></tr><tr><td>Destinataires choisis</td><td>Les comptes sélectionnés</td></tr></tbody></table></li><li><p>Choisissez une ou plusieurs <strong>cibles</strong> : un compte reçoit la communication si son affectation correspond à au moins une d&#39;elles. La direction (PDG et pôles) couvre tous les produits, zones et bureaux.</p></li><li><p><strong>Publier</strong>.</p></li></ol><p>Les destinataires sont prévenus par une <a href="./../notifications.html">notification</a>. Une communication peut être modifiée ou supprimée par ceux qui publient ; la supprimer la retire de l&#39;intranet de tous ses destinataires.</p><h2 id="ressources-partagees" tabindex="-1">Ressources partagées <a class="header-anchor" href="#ressources-partagees" aria-label="Permalink to &quot;Ressources partagées&quot;">​</a></h2><p><strong>Administration → Ressources</strong> gère les documents, procédures, notes, contacts et liens de l&#39;intranet.</p><ol><li><strong>Nouvelle ressource</strong>.</li><li>Choisissez le <strong>type</strong> et saisissez le <strong>titre</strong> et le <strong>texte</strong>, en anglais et en français.</li><li>Selon le type : <ul><li>document : joignez le <strong>fichier</strong> (PDF, bureautique, texte ou image, 2 Mo au plus) ;</li><li>lien : saisissez l&#39;<strong>adresse du lien</strong>.</li></ul></li><li><strong>Produit</strong> : laissez <strong>Général (tout M&#39;City)</strong> pour une ressource visible de tous, ou choisissez un produit actif pour la réserver aux comptes dont le périmètre le couvre. Elle apparaît alors aussi dans l&#39;espace du produit.</li><li><strong>Créer la ressource</strong>.</li></ol><p>Les comptes concernés sont prévenus. Supprimer une ressource supprime aussi son fichier, définitivement. Un fichier n&#39;est téléchargeable qu&#39;après vérification du périmètre du lecteur.</p>',10)])])}const g=t(r,[["render",n]]);export{m as __pageData,g as default};
